text:
Here's a simple water tracker with a goal of 8 glasses. Tap + after each glass and − to undo. It starts fresh each day, and it keeps your count on this device if the app allows it.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #f2f8fc; color: #12384f; text-align: center; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #date { font-size: 14px; opacity: .7; margin-bottom: 20px; }
  #count { font-size: 56px; font-weight: 700; }
  #msg { min-height: 24px; margin: 6px 0 16px; }
  #bar { height: 14px; background: #d6e8f3; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  #fill { height: 100%; width: 0; background: #2a9df4; transition: width .25s; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 320px; margin: 0 auto 24px; }
  .g { width: 36px; height: 48px; border: 2px solid #2a9df4; border-radius: 4px 4px 10px 10px; background: #fff; }
  .g.full { background: #2a9df4; }
  button { font-size: 22px; padding: 10px 24px; margin: 0 6px; border: 0; border-radius: 10px; background: #2a9df4; color: #fff; cursor: pointer; }
  button.alt { background: #8aa9bb; }
  #reset { display: block; margin: 20px auto 0; font-size: 14px; padding: 6px 14px; background: none; color: #12384f; text-decoration: underline; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="alt" id="minus" aria-label="Remove a glass">−</button>
  <button id="plus" aria-label="Add a glass">+ Glass</button>
  <button id="reset">Reset today</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  document.getElementById("date").textContent = new Date().toDateString();

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
    var m = document.getElementById("msg");
    if (n >= GOAL) m.textContent = "Goal reached. Well done!";
    else m.textContent = (GOAL - n) + " more to go";
  }

  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
